import hashlib
import re
from typing import List
from urllib.parse import urljoin

import requests
from bs4 import BeautifulSoup, NavigableString

from langflow.custom import Component
from langflow.io import BoolInput, IntInput, MultilineInput, Output
from langflow.schema import Data


# ---------------------------------------------------------------------------
# Per-source registry -> gold_table_id ({prefix}-t000k), matched by DOMAIN so
# path variants (e.g. /admissions/) and trailing spaces still resolve.
# Must line up with evidence_ground_truth.json:
#   bu  -> bu-t0001 (foreign), bu-t0002 (Thai)
#   ait -> ait-t0001, ait-t0002, ait-t0003 (dormitory)
#   iis -> iis-t0001
# k is a per-SOURCE 1-based counter (t0001, t0002, ...).
# ---------------------------------------------------------------------------
SOURCE_CONFIG = [
    {"matches": ["bu.ac.th"], "prefix": "bu", "n": 2,
     "hints": [["foreign", "international"], ["thai", "thailand"]]},
    {"matches": ["ait.ac.th"], "prefix": "ait", "n": 3, "hints": []},
    {"matches": ["iis.ru.ac.th"], "prefix": "iis", "n": 1, "hints": []},
]


def config_for(url: str) -> dict:
    u = (url or "").strip().lower()
    for cfg in SOURCE_CONFIG:
        if any(m in u for m in cfg["matches"]):
            return cfg
    return {"prefix": "src", "n": 999, "hints": []}


class MultiWebScraper(Component):
    display_name = "Markdown Web Scraper v5"
    description = "Scrapes to Markdown, consolidates fragment/duplicate/subset tables, and marks each table with its gold_table_id."
    icon = "markdown"

    inputs = [
        MultilineInput(
            name="urls",
            display_name="URLs",
            info="Enter URLs (one per line).",
            value="https://ait.ac.th/admissions/tuition-and-fees/",
        ),
        BoolInput(name="skip_nested", display_name="Skip layout-wrapper tables", value=True,
                  info="Drop a <table> that contains another <table> (layout wrapper); keep the real inner table."),
        BoolInput(name="skip_hidden", display_name="Skip hidden/responsive tables", value=True,
                  info="Ignore tables hidden via display:none / aria-hidden / mobile-only classes (responsive duplicates)."),
        BoolInput(name="dedup_tables", display_name="Drop duplicate tables", value=True,
                  info="Drop a table whose content is identical to one already kept."),
        BoolInput(name="merge_same_header", display_name="Merge consecutive same-header tables", value=True,
                  info="Fold fragment tables that share the exact header row into one logical table."),
        BoolInput(name="drop_subset_tables", display_name="Drop column-subset duplicate tables", value=True,
                  info="Drop a table whose column headers are a strict subset of a larger kept table in the same section "
                       "(e.g. a headerless fee-only clone of the full Program+fees table)."),
        BoolInput(name="drop_headerless_cols", display_name="Drop empty/boilerplate columns", value=True,
                  info="Remove columns whose header cell is blank and whose data is empty or button boilerplate "
                       "(e.g. a 'More Information' link column)."),
        IntInput(name="min_rows", display_name="Min rows to keep", value=2, advanced=True),
        IntInput(name="min_cols", display_name="Min cols to keep", value=2, advanced=True),
    ]

    outputs = [
        Output(display_name="Scraped Data List", name="scraped_data", method="scrape_urls"),
        Output(display_name="Merged Markdown", name="merged_data", method="merge_scraped_data"),
        Output(display_name="Table Report", name="table_report", method="report_tables"),
    ]

    # ------------------------------------------------------------------ utils
    def decode_cf_email(self, hex_string: str) -> str:
        try:
            key = int(hex_string[:2], 16)
            return "".join(chr(int(hex_string[i:i + 2], 16) ^ key) for i in range(2, len(hex_string), 2))
        except Exception:
            return "[Email Protected]"

    def clean_cell(self, cell) -> str:
        text = cell.get_text(separator=" ", strip=True)
        text = re.sub(r"\s+", " ", text).strip()
        return text.replace("|", "\\|")

    @staticmethod
    def _is_hidden(tag) -> bool:
        style = (tag.get("style") or "").replace(" ", "").lower()
        if "display:none" in style or "visibility:hidden" in style:
            return True
        if tag.get("aria-hidden") == "true" or tag.has_attr("hidden"):
            return True
        cls = " ".join(tag.get("class") or []).lower()
        return any(k in cls for k in ["hidden", "mobile-only", "sr-only", "visually-hidden", "d-none"])

    def _extract_rows(self, table) -> list:
        raw = []
        for tr in table.find_all("tr"):
            if tr.find_parent("table") is not table:
                continue
            cells = [self.clean_cell(c) for c in tr.find_all(["td", "th"]) if c.find_parent("table") is table]
            if cells:
                raw.append(cells)
        return raw

    @staticmethod
    def _rows_to_md(raw: list) -> str:
        width = max(len(r) for r in raw)
        lines = []
        for i, cells in enumerate(raw):
            cells = cells + [""] * (width - len(cells))
            lines.append("| " + " | ".join(cells) + " |")
            if i == 0:
                lines.append("| " + " | ".join(["---"] * width) + " |")
        return "\n".join(lines)

    @staticmethod
    def _section_index(soup) -> dict:
        """Map id(table) -> section counter that increments at every heading.
        Two tables in different sections must never be merged or subset-dropped,
        even if their header rows are identical (e.g. BU foreign vs Thai tables)."""
        idx = 0
        m = {}
        for el in soup.find_all(["h1", "h2", "h3", "h4", "h5", "h6", "table"]):
            if el.name == "table":
                m[id(el)] = idx
            else:
                idx += 1
        return m

    def _context_text(self, table) -> str:
        """Nearest heading(s) + table text, lowercased — used for hint matching."""
        parts = []
        cap = table.find("caption")
        if cap:
            parts.append(cap.get_text(" ", strip=True))
        for prev in table.find_all_previous(["h1", "h2", "h3", "h4", "h5", "strong", "p"], limit=4):
            parts.append(prev.get_text(" ", strip=True))
        parts.append(table.get_text(" ", strip=True)[:300])
        return " ".join(parts).lower()

    # ------------------------------------------------------- cleanup helpers
    @staticmethod
    def _header_set(rows) -> set:
        return {c for c in (rows[0] if rows else []) if c.strip()}

    @staticmethod
    def _data_cells(rows) -> set:
        s = set()
        for r in rows[1:]:
            for c in r:
                if c.strip():
                    s.add(c)
        return s

    def _mark_subset_drops(self, kept: list) -> None:
        """Mark a kept table as dropped when its column headers are a strict
        subset of another kept table (same section) and their data overlaps.
        Handles either DOM order (full-then-fragment or fragment-then-full)."""
        live = [r for r in kept if not r.get("dropped")]
        for a in live:
            if a.get("dropped"):
                continue
            ha = self._header_set(a["rows"])
            da = self._data_cells(a["rows"])
            if not ha:
                continue
            for b in live:
                if b is a or b.get("dropped") or a["sec"] != b["sec"]:
                    continue
                hb = self._header_set(b["rows"])
                if hb and hb < ha:  # b's columns are a strict subset of a's
                    db = self._data_cells(b["rows"])
                    overlap = len(db & da) / max(len(db), 1)
                    if overlap >= 0.5:
                        b["dropped"] = True
                        b["entry"]["decision"] = "dropped: partial duplicate (columns subset of larger table)"
                        b["table"].decompose()

    @staticmethod
    def _drop_headerless_cols(rows: list) -> list:
        """Remove columns whose header is blank AND whose data is empty or
        button boilerplate (e.g. a 'More Information' link column)."""
        if len(rows) < 2:
            return rows
        header = rows[0]
        ncol = len(header)
        boiler = {"", "more information", "more info", "details", "view", "apply", "read more"}
        drop = set()
        for j in range(ncol):
            if header[j].strip():
                continue
            vals = [(r[j] if j < len(r) else "") for r in rows[1:]]
            nonempty = [v for v in vals if v.strip()]
            if not nonempty or all(v.strip().lower() in boiler for v in nonempty):
                drop.add(j)
        if not drop:
            return rows
        keep = [j for j in range(ncol) if j not in drop]
        if len(keep) < 2:  # never collapse a table below 2 columns
            return rows
        return [[(r[j] if j < len(r) else "") for j in keep] for r in rows]

    # ----------------------------------------------- table consolidation pass
    def _consolidate_tables(self, soup, url, cfg, report):
        """Replace each kept top-level table with a [[pid]] placeholder.

        Returns (placeholders {pid: markdown}, kept_order [{'pid','context'}]).
        Passes: drop nested/hidden/degenerate/exact-dup -> vertical same-header
        merge -> column-subset drop -> headerless-column cleanup -> placeholders.
        Gold ids are assigned AFTER this pass (so hints can reorder).
        """
        kept = []              # survivor records (context computed while in tree)
        seen_hashes = set()
        prev = None            # previous kept record (for same-header merge)
        secmap = self._section_index(soup)

        # ---- pass 1: per-table keep/drop + vertical same-header merge --------
        for n, table in enumerate(soup.find_all("table")):
            sec = secmap.get(id(table))
            raw = self._extract_rows(table)
            nrows = len(raw)
            ncols = max((len(r) for r in raw), default=0)
            reason = "kept"

            if self.skip_nested and table.find("table") is not None:
                reason = "dropped: layout wrapper (contains a nested table)"
            elif self.skip_hidden and self._is_hidden(table):
                reason = "dropped: hidden/responsive"
            elif nrows < self.min_rows or ncols < self.min_cols:
                reason = f"dropped: degenerate ({nrows}x{ncols})"

            sig = tuple(raw[0]) if raw else ()
            content_hash = hashlib.md5(self._rows_to_md(raw).encode("utf-8")).hexdigest()[:10] if raw else ""

            if reason == "kept" and self.dedup_tables and content_hash in seen_hashes:
                reason = "dropped: duplicate"

            entry = {"source": url, "dom_index": n, "rows": nrows, "cols": ncols,
                     "header": " | ".join(sig)[:80], "decision": reason, "pid": None, "table_id": ""}
            report.append(entry)

            if reason != "kept":
                table.decompose()
                continue

            seen_hashes.add(content_hash)

            if (self.merge_same_header and prev is not None and prev["sig"] == sig
                    and prev["sec"] == sec and len(raw) > 1):
                prev["rows"].extend(raw[1:])
                entry["decision"] = "merged (same header, same section) into previous kept table"
                table.decompose()
                continue

            rec = {"table": table, "rows": raw, "sig": sig, "sec": sec,
                   "entry": entry, "context": self._context_text(table), "dropped": False}
            kept.append(rec)
            prev = rec

        # ---- pass 2: drop column-subset (fragment/responsive) duplicates -----
        if self.drop_subset_tables:
            self._mark_subset_drops(kept)

        # ---- pass 3: finalize survivors -> placeholders ----------------------
        placeholders = {}
        kept_order = []
        counter = 0
        for rec in kept:
            if rec.get("dropped"):
                continue
            rows = self._drop_headerless_cols(rec["rows"]) if self.drop_headerless_cols else rec["rows"]
            pid = f"PH_{cfg['prefix']}_{counter:03d}"
            counter += 1
            placeholders[pid] = self._rows_to_md(rows)
            kept_order.append({"pid": pid, "context": rec["context"]})
            rec["entry"]["pid"] = pid
            rec["table"].replace_with(NavigableString(f"\n\n[[{pid}]]\n\n"))

        return placeholders, kept_order

    @staticmethod
    def _assign_gold_ids(kept: list, prefix: str, hints: list) -> dict:
        """kept: ordered [{'pid','context'}]. Returns {pid: '{prefix}-t000k'}."""
        slots = [None] * len(kept)
        used = set()
        for slot, group in enumerate(hints or []):
            if slot >= len(kept):
                break
            for i, rec in enumerate(kept):
                if i in used:
                    continue
                if any(kw in rec["context"] for kw in group):
                    slots[slot] = rec
                    used.add(i)
                    break
        remaining = [rec for i, rec in enumerate(kept) if i not in used]
        for s in range(len(slots)):
            if slots[s] is None and remaining:
                slots[s] = remaining.pop(0)
        mapping = {}
        for slot, rec in enumerate(slots):
            if rec is not None:
                mapping[rec["pid"]] = f"{prefix}-t{slot + 1:04d}"
        return mapping

    # ---------------------------------------------------------- html -> md
    def html_to_markdown(self, element, url):
        if isinstance(element, NavigableString):
            return str(element).strip()
        tag = element.name
        if tag == "a" and element.get("href"):
            href = urljoin(url, element["href"])
            return f" [{element.get_text(strip=True)}]({href}) "
        if tag in ["h1", "h2", "h3", "h4", "h5", "h6"]:
            level = int(tag[1])
            return f"\n\n{'#' * level} {element.get_text(strip=True)}\n"
        if tag == "li":
            return f"\n* {element.get_text(strip=True)}"
        if tag == "p":
            return f"\n\n{element.get_text(strip=True)}\n"
        return "".join(
            self.html_to_markdown(child, url)
            for child in element.children
            if getattr(child, "name", None) not in ["script", "style"]
        )

    # --------------------------------------------------------------- pipeline
    def _scrape(self):
        urls = self.urls
        url_list = [u.strip() for u in urls.split("\n") if u.strip()] if isinstance(urls, str) else urls
        headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"}
        results, report = [], []

        for url in url_list:
            try:
                resp = requests.get(url, headers=headers, timeout=15)
                resp.raise_for_status()
                soup = BeautifulSoup(resp.text, "html.parser")

                for cf_tag in soup.find_all(class_="__cf_email__"):
                    enc = cf_tag.get("data-cfemail")
                    if enc:
                        cf_tag.replace_with(self.decode_cf_email(enc))
                for selector in [".o-breadcrumb", "nav", "footer", "header", "script", "style"]:
                    for tag in soup.select(selector):
                        tag.decompose()

                page_title = soup.title.string if soup.title else url
                main_body = soup.find("main") or soup.find("article") or soup.find("body")

                cfg = config_for(url)
                placeholders, kept_order = self._consolidate_tables(main_body or soup, url, cfg, report)

                # assign gold ids (hints first, then DOM order), then fill the report
                mapping = self._assign_gold_ids(kept_order, cfg["prefix"], cfg["hints"])
                for r in report:
                    if r.get("pid") in mapping:
                        r["table_id"] = mapping[r["pid"]]

                md = f"# PAGE: {page_title}\nURL: {url}\n\n"
                md += self.html_to_markdown(main_body, url) if main_body else "No content found."

                # substitute placeholders with marker-wrapped whole tables carrying the gold id
                for pid, table_md in placeholders.items():
                    gold_id = mapping.get(pid, f"{cfg['prefix']}-tXXXX")
                    block = f"<!-- TABLE id={gold_id} source={url} -->\n{table_md}\n<!-- /TABLE -->"
                    md = md.replace(f"[[{pid}]]", block)

                results.append(Data(data={"text": re.sub(r"\n{3,}", "\n\n", md), "source": url}))
            except Exception as e:
                results.append(Data(data={"text": f"Error: {e}", "source": url}))
                report.append({"source": url, "dom_index": -1, "rows": 0, "cols": 0,
                               "header": "", "decision": f"error: {e}", "pid": None, "table_id": ""})

        return results, report

    # ----------------------------------------------------------------- outputs
    def scrape_urls(self) -> List[Data]:
        results, _ = self._scrape()
        return results

    def merge_scraped_data(self) -> Data:
        results, _ = self._scrape()
        return Data(data={"text": "\n\n---\n\n".join(item.text for item in results)})

    def report_tables(self) -> Data:
        _, report = self._scrape()
        n_kept = sum(1 for r in report if r["decision"] == "kept")
        lines = [f"TABLE INVENTORY — {len(report)} <table> elements found, {n_kept} kept as logical tables", ""]
        lines.append(f"{'gold_table_id':14} {'src':24} {'dom#':>4} {'rows':>4} {'cols':>4}  decision | header")
        lines.append("-" * 110)
        for r in report:
            src = r["source"].split("//")[-1][:24]
            lines.append(f"{r['table_id']:14} {src:24} {r['dom_index']:>4} {r['rows']:>4} {r['cols']:>4}  {r['decision']} | {r['header']}")
        self.status = "\n".join(lines)
        return Data(data={"text": "\n".join(lines)})

import hashlib
import json
import re
from typing import List

import httpx
from langchain_text_splitters import CharacterTextSplitter

from langflow.custom import Component
from langflow.io import (
    BoolInput,
    DropdownInput,
    FloatInput,
    HandleInput,
    IntInput,
    MessageTextInput,
    Output,
)
from langflow.schema import Data


# Value-preserving EXTRACTIVE prompt. One sentence per row, copy every value.
# {{ }} are the literal JSON braces the model must emit.
EXTRACTIVE_PROMPT = """You convert ONE tuition/fee table into COMPLETE factual sentences. You are NOT summarizing — you must keep every value.

Source: {source}
Section: {section}
{group_line}Column headers: {headers}

Table rows (markdown):
{rows_md}

Write EXACTLY ONE sentence per data row, in the same order. Each sentence MUST:
- begin with the row label (the first column){group_clause}
- then state every other column as "<column header>: <value>"
- copy every number, comma, currency symbol, dash, and unit EXACTLY as written — never round, translate, merge, or skip a value
- never invent a row or a number that is not in the table above

Respond ONLY with JSON: {{"extractive": "<sentence 1>\\n<sentence 2>\\n..."}}
No commentary, no headings, no markdown.{retry_note}
"""


class MultiLinkAITSummarizer(Component):
    display_name = "V3 Extractive Table Summarizer (M2)"
    description = "Summarizes each table into COMPLETE value-preserving sentences (group-aware, coverage-checked); carries prose through as text chunks."
    icon = "Ollama"

    inputs = [
        MessageTextInput(
            name="base_url",
            display_name="Ollama API URL",
            value="https://ollama.aitgpt.dev.brain.cs.ait.ac.th",
        ),
        DropdownInput(name="model_name", display_name="Model Name", options=[], refresh_button=True),
        HandleInput(
            name="input_data",
            display_name="Scraped Data (List)",
            info="Connect the Markdown Web Scraper output here.",
            input_types=["Data"],
            is_list=True,
        ),
        MessageTextInput(
            name="system_message",
            display_name="System Message",
            value="You are a data extractor. Copy every number and value from the table exactly. "
            "Never omit a row and never invent a value. Respond ONLY with valid JSON of the form "
            "{\"extractive\": \"...\"}.",
        ),
        FloatInput(name="temperature", display_name="Temperature", value=0.1),
        IntInput(name="chunk_size", display_name="Prose Chunk Size", value=1000),
        IntInput(name="chunk_overlap", display_name="Prose Chunk Overlap", value=200),
        FloatInput(name="coverage_threshold", display_name="Min value coverage", value=0.9, advanced=True,
                   info="If the LLM summary preserves fewer than this fraction of the table's numbers, retry once then fall back."),
        IntInput(name="max_rows_per_call", display_name="Max rows per LLM call", value=20, advanced=True,
                 info="Tall groups are summarized in row-batches of this size so nothing is truncated."),
        BoolInput(name="deterministic_fallback", display_name="Deterministic fallback on low coverage", value=True, advanced=True,
                  info="If the LLM still drops values after a retry, substitute a complete deterministic linearization (flagged in metadata)."),
        BoolInput(name="chunk_per_group", display_name="One chunk per program group", value=False, advanced=True,
                  info="Emit a separate chunk per detected group (e.g. per IIS program) instead of one chunk per table."),
    ]

    outputs = [
        Output(display_name="Summary List", name="summary_list", method="process_summaries"),
    ]

    async def update_build_config(self, build_config: dict, field_value: str, field_name: str | None = None):
        if field_name == "model_name" or not build_config["model_name"]["options"]:
            try:
                base_url = build_config["base_url"]["value"].rstrip("/")
                async with httpx.AsyncClient() as client:
                    response = await client.get(f"{base_url}/api/tags")
                    if response.status_code == 200:
                        build_config["model_name"]["options"] = [m["name"] for m in response.json().get("models", [])]
            except Exception:
                build_config["model_name"]["options"] = ["qwen3:8b", "qwen2.5:7b"]
        return build_config

    # ------------------------------------------------- markdown segmentation
    @staticmethod
    def _is_sep(line: str) -> bool:
        s = line.strip()
        return "-" in s and set(s.replace(" ", "")) <= set("|-:") and "|" in s

    @staticmethod
    def _is_hr(line: str) -> bool:
        s = line.strip()
        return len(s) >= 3 and set(s) <= set("-")

    @classmethod
    def _read_row(cls, lines, k):
        parts = [lines[k].rstrip()]
        k += 1
        while k < len(lines):
            cur = re.sub(r"\s+", " ", " ".join(p.strip() for p in parts)).strip()
            if cur.endswith("|"):
                break
            nxt = lines[k].strip()
            if nxt == "" or nxt.startswith("#"):
                break
            parts.append(nxt)
            k += 1
        return re.sub(r"\s+", " ", " ".join(p.strip() for p in parts)).strip(), k

    @classmethod
    def _parse_table(cls, lines, i):
        header, k = cls._read_row(lines, i)
        j = k
        while j < len(lines) and lines[j].strip() == "":
            j += 1
        if j >= len(lines) or not cls._is_sep(lines[j]):
            return None
        rows = [header, lines[j].strip()]
        k = j + 1
        while k < len(lines):
            sl = lines[k].strip()
            if sl == "" or sl.startswith("#") or not sl.startswith("|"):
                break
            row, k = cls._read_row(lines, k)
            rows.append(row)
        return "\n".join(rows), k

    def _segments(self, text: str):
        """Yield (kind, content, table_id) in document order (table_id from marker)."""
        if "<!-- TABLE" in text:
            pattern = re.compile(r"<!-- TABLE id=(\S+) source=(.*?) -->\n(.*?)\n<!-- /TABLE -->", re.DOTALL)
            last = 0
            for m in pattern.finditer(text):
                yield ("prose", text[last:m.start()], None)
                yield ("table", m.group(3).strip(), m.group(1))
                last = m.end()
            yield ("prose", text[last:], None)
            return
        lines = text.split("\n")
        prose: list[str] = []
        i = 0
        while i < len(lines):
            s = lines[i].strip()
            if s.startswith("|") and not self._is_sep(lines[i]):
                res = self._parse_table(lines, i)
                if res:
                    yield ("prose", "\n".join(prose), None)
                    prose = []
                    table_md, k = res
                    yield ("table", table_md, None)
                    i = k
                    continue
            prose.append(lines[i])
            i += 1
        yield ("prose", "\n".join(prose), None)

    # ------------------------------------------------------- table structure
    @staticmethod
    def _parse_md_table(md: str):
        lines = [l for l in md.strip().split("\n") if l.strip()]

        def cells(line):
            parts = re.split(r"(?<!\\)\|", line)
            parts = [p.strip().replace("\\|", "|") for p in parts]
            if parts and parts[0] == "":
                parts = parts[1:]
            if parts and parts[-1] == "":
                parts = parts[:-1]
            return parts

        if not lines:
            return [], []
        header = cells(lines[0])
        data = [cells(l) for l in lines[2:]] if len(lines) > 2 else []
        w = max([len(header)] + [len(r) for r in data]) if data else len(header)
        header = header + [""] * (w - len(header))
        data = [r + [""] * (w - len(r)) for r in data]
        return header, data

    @staticmethod
    def _drop_headerless_cols(header, rows):
        boiler = {"", "more information", "more info", "details", "view", "apply", "read more"}
        drop = set()
        for j, h in enumerate(header):
            if h.strip():
                continue
            col = [r[j] for r in rows]
            ne = [c for c in col if c.strip()]
            if not ne or all(c.strip().lower() in boiler for c in ne):
                drop.add(j)
        if not drop:
            return header, rows
        keep = [j for j in range(len(header)) if j not in drop]
        if len(keep) < 2:
            return header, rows
        return [header[j] for j in keep], [[r[j] for j in keep] for r in rows]

    @staticmethod
    def _split_groups(rows):
        """A row with only col0 filled is a group sub-header (e.g. IIS program)."""
        groups = []
        cur_label = None
        cur = []
        for r in rows:
            if r[0].strip() and not any(c.strip() for c in r[1:]):
                if cur:
                    groups.append((cur_label, cur))
                cur_label = r[0].strip()
                cur = []
            else:
                cur.append(r)
        if cur:
            groups.append((cur_label, cur))
        return groups

    @staticmethod
    def _rows_to_md(header, rows):
        lines = ["| " + " | ".join(header) + " |",
                 "| " + " | ".join(["---"] * len(header)) + " |"]
        for r in rows:
            lines.append("| " + " | ".join(r) + " |")
        return "\n".join(lines)

    @staticmethod
    def _linearize_group(header, glabel, rows):
        """Complete deterministic linearization (guaranteed value-preserving)."""
        out = []
        for r in rows:
            label = r[0].strip() or "(row)"
            prefix = f"{glabel}, {label}" if glabel else label
            parts = [f"{header[j]}: {r[j].strip()}" for j in range(1, len(header)) if r[j].strip()]
            out.append(f"{prefix} — " + "; ".join(parts) + ".")
        return "\n".join(out)

    _NUM = re.compile(r"\d[\d,]*(?:\.\d+)?")

    @classmethod
    def _numbers(cls, s: str) -> set:
        return {n.rstrip(".") for n in cls._NUM.findall(s or "")}

    @classmethod
    def _coverage(cls, source_md: str, summary: str):
        tn = cls._numbers(source_md)
        if not tn:
            return 1.0, set()
        sn = cls._numbers(summary)
        return len(tn & sn) / len(tn), (tn - sn)

    # ------------------------------------------------------------ summarize
    @staticmethod
    def _unwrap(text: str) -> str:
        t = re.sub(r"<think>.*?</think>", "", text or "", flags=re.DOTALL).strip()
        t = re.sub(r"^```(?:json)?\s*|\s*```$", "", t, flags=re.IGNORECASE).strip()
        if t.startswith("{"):
            try:
                obj = json.loads(t)
                if isinstance(obj, dict):
                    if isinstance(obj.get("extractive"), str):
                        return obj["extractive"].strip()
                    strings = [v for v in obj.values() if isinstance(v, str)]
                    if strings:
                        return max(strings, key=len).strip()
            except json.JSONDecodeError:
                pass
        return t

    async def _call(self, client, header, glabel, rows, source, section, retry_note=""):
        rows_md = self._rows_to_md(header, rows)
        group_line = f"Program group: {glabel}\n" if glabel else ""
        group_clause = f', prefixed with the program group "{glabel}"' if glabel else ""
        prompt = EXTRACTIVE_PROMPT.format(
            source=source or "the source page", section=section or "-",
            group_line=group_line, headers=" | ".join(header),
            rows_md=rows_md, group_clause=group_clause, retry_note=retry_note,
        )
        payload = {
            "model": self.model_name,
            "prompt": prompt,
            "system": self.system_message,
            "stream": False,
            "format": "json",
            "options": {"temperature": self.temperature, "num_ctx": 8192},
        }
        resp = await client.post(f"{self.base_url.rstrip('/')}/api/generate", json=payload)
        resp.raise_for_status()
        return self._unwrap(resp.json().get("response", "") or "")

    async def _summarize_group(self, client, header, glabel, rows, source, section):
        """LLM extraction with coverage guard + retry + deterministic fallback.
        Returns (text, coverage, method)."""
        max_rows = max(1, int(self.max_rows_per_call))
        batches = [rows[i:i + max_rows] for i in range(0, len(rows), max_rows)] or [rows]
        texts, methods = [], []
        for batch in batches:
            batch_md = self._rows_to_md(header, batch)
            try:
                out = await self._call(client, header, glabel, batch, source, section)
            except Exception:
                out = ""
            cov, missing = self._coverage(batch_md, out)
            method = "llm"
            if out and cov < self.coverage_threshold:
                note = ("\nYou previously omitted these values — include every one of them, "
                        f"each bound to its row: {', '.join(sorted(missing))}.")
                try:
                    out2 = await self._call(client, header, glabel, batch, source, section, retry_note=note)
                    if self._coverage(batch_md, out2)[0] > cov:
                        out, cov = out2, self._coverage(batch_md, out2)[0]
                except Exception:
                    pass
            if (not out or cov < self.coverage_threshold) and self.deterministic_fallback:
                out = self._linearize_group(header, glabel, batch)
                cov, method = 1.0, "deterministic_fallback"
            texts.append(out)
            methods.append(method)
        full = "\n".join(t for t in texts if t)
        overall_cov = self._coverage(self._rows_to_md(header, rows), full)[0]
        method = "deterministic_fallback" if "deterministic_fallback" in methods else "llm"
        return full, overall_cov, method

    # --------------------------------------------------------------- main
    async def process_summaries(self) -> List[Data]:
        if not self.input_data:
            return []
        pages = self.input_data if isinstance(self.input_data, list) else [self.input_data]
        prose_splitter = CharacterTextSplitter(
            chunk_size=self.chunk_size, chunk_overlap=self.chunk_overlap, separator="\n"
        )
        results: list[Data] = []
        ccount = 0
        tcount = 0
        last_error = ""

        def mk(text, *, chunk_id, gold_id, ctype, source, section, n_rows=0, coverage=None, method=""):
            data = {
                "text": text,
                "chunk_id": chunk_id,
                "table_id": gold_id,
                "gold_table_id": gold_id,
                "type": ctype,
                "source": source,
                "section": section,
                "n_rows": n_rows,
                "content_hash": hashlib.md5(text.encode("utf-8")).hexdigest()[:10],
            }
            if coverage is not None:
                data["value_coverage"] = round(coverage, 3)
                data["summarizer"] = method
            return Data(data=data)

        async with httpx.AsyncClient(timeout=180.0) as client:
            for page in pages:
                pdata = page.data if hasattr(page, "data") else {}
                text = pdata.get("text", "") or ""
                source = pdata.get("source", "Unknown")
                if not text or "Error:" in text[:20]:
                    continue

                section = ""
                for kind, payload, tid in self._segments(text):
                    if kind == "prose":
                        for raw in payload.split("\n"):
                            st = raw.strip()
                            if st.startswith("#"):
                                section = st.lstrip("#").strip()
                        body = re.sub(r"<!--.*?-->", "", payload).strip()
                        if not body:
                            continue
                        for piece in prose_splitter.split_text(body):
                            piece = piece.strip()
                            if not piece or self._is_hr(piece):
                                continue
                            results.append(mk(piece, chunk_id=f"c{ccount:04d}", gold_id="",
                                              ctype="text", source=source, section=section))
                            ccount += 1
                        continue

                    # ---- table: extract into complete value-preserving sentences ----
                    gold_id = tid if tid else f"t{tcount:04d}"
                    tcount += 1
                    header, rows = self._parse_md_table(payload)
                    header, rows = self._drop_headerless_cols(header, rows)
                    if not header or not rows:
                        continue
                    groups = self._split_groups(rows)
                    n_data = sum(len(g_rows) for _, g_rows in groups)

                    group_texts = []
                    covs = []
                    methods = []
                    try:
                        for glabel, g_rows in groups:
                            gtext, gcov, gmethod = await self._summarize_group(
                                client, header, glabel, g_rows, source, section
                            )
                            group_texts.append((glabel, gtext))
                            covs.append(gcov)
                            methods.append(gmethod)
                    except Exception as e:
                        last_error = str(e)

                    table_cov = round(sum(covs) / len(covs), 3) if covs else 0.0
                    table_method = "deterministic_fallback" if "deterministic_fallback" in methods else "llm"

                    if self.chunk_per_group and len(groups) > 1:
                        for k, (glabel, gtext) in enumerate(group_texts):
                            head = f"{section} — {glabel}" if section and glabel else (glabel or section)
                            body = f"{head}\n{gtext}" if head else gtext
                            results.append(mk(body, chunk_id=f"{gold_id}-g{k:02d}", gold_id=gold_id,
                                              ctype="table_summary", source=source,
                                              section=glabel or section, n_rows=len(group_texts[k][1].splitlines()),
                                              coverage=covs[k], method=methods[k]))
                    else:
                        summary = "\n".join(t for _, t in group_texts if t)
                        body = f"{section}\n{summary}" if section else summary
                        results.append(mk(body, chunk_id=gold_id, gold_id=gold_id,
                                          ctype="table_summary", source=source, section=section,
                                          n_rows=n_data, coverage=table_cov, method=table_method))

        # Show the ROWS in the panel (grid), not a count sentence.
        if results:
            self.status = results
        elif last_error:
            self.status = f"Table summarize error: {last_error}"
        return results
